import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    if df['sex'].dtype == object:
        df['sex'] = df['sex'].str.strip()
    df['island'] = df['island'].replace('Bisco', 'Biscoe')
    return df

def answer(df):
    df = clean(df)
    df = df.dropna(subset=['sex'])
    result = df.groupby('sex')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in result.items()}
